insert into public.goonj_campaigns (slug, name, kind, status, is_template, hero, form, points, seo) values ('limited-release', 'Limited release (default page)', 'default', 'published', false, '{"badge":"Welcome to Goonj","title":"Be one of the first. Join something special.","titleAccent":"Join something special.","subtitle":"A personal space for professionals to unlock their true potential.","bullets":["No complicated learning. Just conversations.","No big commitment. Just small moments.","No waiting months. Just days to make progress."],"ctaLabel":"Get Early Access","trustLine":"Start Free. Leave Anytime. Always Private.","media":{"type":"image","url":"/goonj/lr/aarya.webp","alt":"Aarya, a Goonj AI mentor"}}'::jsonb, '{"title":"Experience Goonj before the world does","subtitle":"Fill in your details to get early access.","continueLabel":"Count me in","submitLabel":"Request Early Access","twoStep":true,"successTitle":"Thanks, {first_name}!","successBody":"Thank you for your submission. You have been added to our waiting list. If you are selected for the limited release, we will be in touch with further details.","fields":[{"key":"first_name","label":"First name","type":"text","required":true},{"key":"last_name","label":"Last name","type":"text","required":true},{"key":"email","label":"Email address","type":"email","required":true},{"key":"phone","label":"Phone","type":"tel","required":true},{"key":"profile_link","label":"Your profile","type":"url","required":false,"placeholder":"Paste your profile link"}]}'::jsonb, '{"eyebrow":"Limited release","title":"Early ⬩ Involved ⬩ Valued","image":{"type":"image","url":"/goonj/lr/aarya.webp","alt":"Aarya, a Goonj AI mentor"},"items":[{"title":"You Are One Of The Few","body":"Goonj isn''t open to everyone yet. You are part of a special group invited to experience it first."},{"title":"You Are Here For A Reason","body":"We believe your perspective, experiences, and way of seeing things can bring something meaningful to Goonj."},{"title":"You Get To Discover It Early","body":"You will experience Goonj while it''s still new, before it becomes available to a much larger audience."},{"title":"Your Feedback Matters More","body":"Your honest reactions will help us understand what feels useful, what feels natural, and what needs improvement."},{"title":"You Are Closer To The Team","body":"As an early user, you will have a more direct connection with the people building Goonj and the work happening behind it."},{"title":"You Are Part Of What Comes Next","body":"Your experience can help us understand what people need, what works, and what deserves more attention as Goonj grows."}]}'::jsonb, '{"title":"Goonj AI - Get Early Access Before Our Public Launch","description":"A personal space for professionals to unlock their true potential. Join the Goonj limited release."}'::jsonb) on conflict (slug) do nothing;
